package com.alibaba.nacos.naming.core.v2.metadata;

import com.alibaba.nacos.naming.core.v2.event.metadata.MetadataEvent;
import com.alibaba.nacos.naming.core.v2.pojo.Service;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.Optional;
import java.util.concurrent.TimeUnit;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Test for {@link NamingMetadataManager} focusing on the fix for issue #14648.
 * Tests the behavior when instance re-registers with new metadata values.
 */
@ExtendWith(MockitoExtension.class)
public class NamingMetadataManagerTest {

    private NamingMetadataManager namingMetadataManager;
    private Service service;

    private static final String METADATA_ID = "127.0.0.1:8080";
    private static final String METADATA_ID_2 = "127.0.0.1:8081";

    @BeforeEach
    public void setUp() {
        namingMetadataManager = new NamingMetadataManager();
        service = Service.newService("test-namespace", "test-group", "test-service");
    }

    @AfterEach
    public void tearDown() {
        // Clean up if needed
    }

    /**
     * Test the core fix for issue #14648:
     * When instance re-registers (expired=false), old metadata should be removed
     * so new registration values can take effect.
     */
    @Test
    public void testReRegisterRemovesOldMetadata() throws Exception {
        // Step 1: Simulate console updating metadata (enabled=true)
        InstanceMetadata consoleMetadata = new InstanceMetadata();
        consoleMetadata.setEnabled(true);
        consoleMetadata.getExtendData().put("source", "console");

        namingMetadataManager.updateInstanceMetadata(service, METADATA_ID, consoleMetadata);

        // Verify console metadata is stored
        Optional<InstanceMetadata> storedBefore = namingMetadataManager.getInstanceMetadata(service, METADATA_ID);
        assertTrue(storedBefore.isPresent());
        assertTrue(storedBefore.get().isEnabled());
        assertEquals("console", storedBefore.get().getExtendData().get("source"));

        // Step 2: Simulate client re-registration by triggering metadata event
        // The event should be handled internally by NamingMetadataManager
        // We need to simulate this by calling a method that triggers the event handling
        // Since handleInstanceMetadataEvent is private, we need to trigger it through public API

        // Create and publish the event - NamingMetadataManager should be subscribed to these events
        MetadataEvent.InstanceMetadataEvent event = new MetadataEvent.InstanceMetadataEvent(
            service, METADATA_ID, false);

        // The manager should handle this event internally
        // We'll verify the effect by checking if metadata was removed
        namingMetadataManager.onEvent(event);

        // Step 3: Verify the old metadata was removed (key assertion for the patch)
        assertFalse(namingMetadataManager.containInstanceMetadata(service, METADATA_ID));

        // Step 4: Now client can register with new metadata (enabled=false)
        InstanceMetadata clientMetadata = new InstanceMetadata();
        clientMetadata.setEnabled(false);
        clientMetadata.getExtendData().put("source", "client");

        namingMetadataManager.updateInstanceMetadata(service, METADATA_ID, clientMetadata);

        // Step 5: Verify the new client metadata is what's stored
        Optional<InstanceMetadata> storedAfter = namingMetadataManager.getInstanceMetadata(service, METADATA_ID);
        assertTrue(storedAfter.isPresent());
        assertFalse(storedAfter.get().isEnabled());
        assertEquals("client", storedAfter.get().getExtendData().get("source"));
    }

    /**
     * Test that expired metadata is NOT removed on expired events.
     * This preserves the existing behavior for expired metadata cleanup.
     */
    @Test
    public void testExpiredMetadataNotRemoved() throws Exception {
        // Setup: Add metadata
        InstanceMetadata metadata = new InstanceMetadata();
        metadata.setEnabled(true);
        metadata.getExtendData().put("status", "active");

        namingMetadataManager.updateInstanceMetadata(service, METADATA_ID, metadata);

        // Verify metadata exists
        assertTrue(namingMetadataManager.containInstanceMetadata(service, METADATA_ID));

        // Publish expired event (expired=true)
        MetadataEvent.InstanceMetadataEvent event = new MetadataEvent.InstanceMetadataEvent(
            service, METADATA_ID, true);

        namingMetadataManager.onEvent(event);

        // Verify metadata still exists (not removed for expired events)
        assertTrue(namingMetadataManager.containInstanceMetadata(service, METADATA_ID));

        Optional<InstanceMetadata> stored = namingMetadataManager.getInstanceMetadata(service, METADATA_ID);
        assertTrue(stored.isPresent());
        assertEquals("active", stored.get().getExtendData().get("status"));
    }

    /**
     * Test that when no metadata exists, event handling doesn't cause issues.
     * This tests the boundary condition.
     */
    @Test
    public void testEventWithNoExistingMetadata() throws Exception {
        // Verify no metadata exists initially
        assertFalse(namingMetadataManager.containInstanceMetadata(service, METADATA_ID));

        // Publish event for non-existing metadata (both expired and non-expired)
        MetadataEvent.InstanceMetadataEvent event = new MetadataEvent.InstanceMetadataEvent(
            service, METADATA_ID, false);

        namingMetadataManager.onEvent(event);

        // Should not throw exception and metadata should still not exist
        assertFalse(namingMetadataManager.containInstanceMetadata(service, METADATA_ID));

        // Test with expired=true as well
        MetadataEvent.InstanceMetadataEvent expiredEvent = new MetadataEvent.InstanceMetadataEvent(
            service, METADATA_ID, true);

        namingMetadataManager.onEvent(expiredEvent);

        assertFalse(namingMetadataManager.containInstanceMetadata(service, METADATA_ID));
    }

    /**
     * Test multiple metadata entries for same service are handled independently.
     * Only the targeted metadata should be affected.
     */
    @Test
    public void testMultipleMetadataEntriesIndependentHandling() throws Exception {
        // Setup: Add two metadata entries
        InstanceMetadata metadata1 = new InstanceMetadata();
        metadata1.setEnabled(true);
        metadata1.getExtendData().put("id", "1");

        InstanceMetadata metadata2 = new InstanceMetadata();
        metadata2.setEnabled(false);
        metadata2.getExtendData().put("id", "2");

        namingMetadataManager.updateInstanceMetadata(service, METADATA_ID, metadata1);
        namingMetadataManager.updateInstanceMetadata(service, METADATA_ID_2, metadata2);

        // Verify both exist
        assertTrue(namingMetadataManager.containInstanceMetadata(service, METADATA_ID));
        assertTrue(namingMetadataManager.containInstanceMetadata(service, METADATA_ID_2));

        // Publish re-registration event for first metadata only (expired=false)
        MetadataEvent.InstanceMetadataEvent event = new MetadataEvent.InstanceMetadataEvent(
            service, METADATA_ID, false);

        namingMetadataManager.onEvent(event);

        // Verify first metadata was removed, second remains
        assertFalse(namingMetadataManager.containInstanceMetadata(service, METADATA_ID));
        assertTrue(namingMetadataManager.containInstanceMetadata(service, METADATA_ID_2));

        // Update with new metadata for first instance
        InstanceMetadata newMetadata1 = new InstanceMetadata();
        newMetadata1.setEnabled(false);
        newMetadata1.getExtendData().put("id", "1-updated");

        namingMetadataManager.updateInstanceMetadata(service, METADATA_ID, newMetadata1);

        // Verify both metadata entries
        Optional<InstanceMetadata> stored1 = namingMetadataManager.getInstanceMetadata(service, METADATA_ID);
        Optional<InstanceMetadata> stored2 = namingMetadataManager.getInstanceMetadata(service, METADATA_ID_2);

        assertTrue(stored1.isPresent());
        assertTrue(stored2.isPresent());

        assertFalse(stored1.get().isEnabled());
        assertEquals("1-updated", stored1.get().getExtendData().get("id"));

        assertFalse(stored2.get().isEnabled());
        assertEquals("2", stored2.get().getExtendData().get("id"));
    }

    /**
     * Test the complete realistic flow as described in issue #14648.
     */
    @Test
    public void testCompleteReRegistrationFlow() throws Exception {
        // Initial: Client registers with enabled=false
        InstanceMetadata initialMetadata = new InstanceMetadata();
        initialMetadata.setEnabled(false);
        initialMetadata.getExtendData().put("weight", "1.0");

        namingMetadataManager.updateInstanceMetadata(service, METADATA_ID, initialMetadata);

        // Console updates to enabled=true
        InstanceMetadata consoleUpdate = new InstanceMetadata();
        consoleUpdate.setEnabled(true);
        consoleUpdate.getExtendData().put("weight", "2.0");
        consoleUpdate.getExtendData().put("updatedBy", "console");

        namingMetadataManager.updateInstanceMetadata(service, METADATA_ID, consoleUpdate);

        // Verify console update is applied
        Optional<InstanceMetadata> afterConsole = namingMetadataManager.getInstanceMetadata(service, METADATA_ID);
        assertTrue(afterConsole.isPresent());
        assertTrue(afterConsole.get().isEnabled());
        assertEquals("console", afterConsole.get().getExtendData().get("updatedBy"));

        // Simulate client re-registration event (expired=false)
        MetadataEvent.InstanceMetadataEvent reRegisterEvent = new MetadataEvent.InstanceMetadataEvent(
            service, METADATA_ID, false);

        namingMetadataManager.onEvent(reRegisterEvent);

        // Verify old metadata was removed
        assertFalse(namingMetadataManager.containInstanceMetadata(service, METADATA_ID));

        // Client re-registers with new values
        InstanceMetadata clientReRegister = new InstanceMetadata();
        clientReRegister.setEnabled(false); // Client wants disabled
        clientReRegister.getExtendData().put("weight", "3.0");
        clientReRegister.getExtendData().put("registeredBy", "client");

        namingMetadataManager.updateInstanceMetadata(service, METADATA_ID, clientReRegister);

        // Verify client's values take precedence
        Optional<InstanceMetadata> finalMetadata = namingMetadataManager.getInstanceMetadata(service, METADATA_ID);
        assertTrue(finalMetadata.isPresent());
        assertFalse(finalMetadata.get().isEnabled()); // Should be false (client's value)
        assertEquals("3.0", finalMetadata.get().getExtendData().get("weight"));
        assertEquals("client", finalMetadata.get().getExtendData().get("registeredBy"));
        // Console's "updatedBy" should not be present anymore since metadata was removed
        assertFalse(finalMetadata.get().getExtendData().containsKey("updatedBy"));
    }

    /**
     * Additional test: Verify that expired=true events don't remove metadata
     * but still update expired info.
     */
    @Test
    public void testExpiredEventUpdatesExpiredInfo() throws Exception {
        // Setup: Add metadata
        InstanceMetadata metadata = new InstanceMetadata();
        metadata.setEnabled(true);

        namingMetadataManager.updateInstanceMetadata(service, METADATA_ID, metadata);

        // Verify metadata exists
        assertTrue(namingMetadataManager.containInstanceMetadata(service, METADATA_ID));

        // Publish expired event
        MetadataEvent.InstanceMetadataEvent event = new MetadataEvent.InstanceMetadataEvent(
            service, METADATA_ID, true);

        namingMetadataManager.onEvent(event);

        // Metadata should still exist (not removed for expired events)
        assertTrue(namingMetadataManager.containInstanceMetadata(service, METADATA_ID));
    }

    /**
     * Test edge case: Verify that if metadata doesn't exist, 
     * the method doesn't throw exception even when expired=false.
     */
    @Test
    public void testNonExistentMetadataWithReRegistration() throws Exception {
        // Ensure metadata doesn't exist
        assertFalse(namingMetadataManager.containInstanceMetadata(service, METADATA_ID));

        // Publish re-registration event for non-existent metadata
        MetadataEvent.InstanceMetadataEvent event = new MetadataEvent.InstanceMetadataEvent(
            service, METADATA_ID, false);

        // Should not throw exception
        namingMetadataManager.onEvent(event);

        // Still should not exist
        assertFalse(namingMetadataManager.containInstanceMetadata(service, METADATA_ID));
    }
}

